parameters.command:
cd /tmp && python3 -c "
import os, neo4j
from collections import defaultdict, deque
d=neo4j.GraphDatabase.driver(os.environ['NEO4J_URI'],auth=(os.environ['NEO4J_USERNAME'],os.environ['NEO4J_PASSWORD']))
adj=defaultdict(list); nodes=[]
with d.session() as s:
  nodes=[r['n'] for r in s.run('MATCH (n:UndergroundStation) RETURN n.name AS n')]
  for r in s.run('MATCH (a:UndergroundStation)-[:LINK]->(b:UndergroundStation) RETURN a.name AS a,b.name AS b'): adj[r['a']].append(r['b'])
bc=dict.fromkeys(nodes,0.0)
for src in nodes:
  S=[];P=defaultdict(list);sig=defaultdict(float);sig[src]=1;dist={src:0};Q=deque([src])
  while Q:
    v=Q.popleft();S.append(v)
    for w in adj[v]:
      if w not in dist: dist[w]=dist[v]+1;Q.append(w)
      if dist[w]==dist[v]+1: sig[w]+=sig[v];P[w].append(v)
  delta=defaultdict(float)
  while S:
    w=S.pop()
    for v in P[w]: delta[v]+=sig[v]/sig[w]*(1+delta[w])
    if w!=src: bc[w]+=delta[w]
print(bc['Westminster'],bc['Waterloo'])
"

