import json,sys
rows=json.load(open(sys.argv[1]))
adj={};name={}
for r in rows:
    adj.setdefault(r['s'],[]).append(r['t']); name[r['s']]=r['sn']; name[r['t']]=r['tn']
for k in adj: adj[k]=sorted(set(adj[k]))
target=[303,228,143,35,138,0,259,197,211,194,134,19,141,214,28,144,10,73,161,3,9,244,289,249,127,115,69,217,38,135,270,24]
src=303;MAX=4
def run(variant,order):
    res=[];par={}
    if variant=='push':
        vis={src};st=[(src,src,0)]
        while st:
            s,n,w=st.pop()
            if w>MAX: continue
            res.append(n);par[n]=s
            for t in order(adj.get(n,[])):
                if t not in vis: vis.add(t); st.append((n,t,w+1))
    else:
        vis=set();st=[(src,src,0)]
        while st:
            s,n,w=st.pop()
            if n in vis: continue
            if w>MAX:
                if variant=='pop_mark': vis.add(n)
                continue
            vis.add(n);res.append(n);par[n]=s
            for t in order(adj.get(n,[])):
                if t not in vis: st.append((n,t,w+1))
    return res,par
for v in ['push','pop_mark','pop_nomark']:
    for on,o in [('asc',lambda l:l),('desc',lambda l:l[::-1])]:
        res,par=run(v,o)
        print(v,on,res==target,len(res))
        if res==target:
            def path(n):
                p=[n]
                while p[-1]!=src: p.append(par[p[-1]])
                return [name[x] for x in p[::-1]]
            leaves=[n for n in res if n not in [par[m] for m in res if m!=src]]
            for l in leaves: print(json.dumps(path(l)))
