ok_pre=True
kids={n:[] for n in order}
for n in order[1:]: kids[par[n]].append(n)
pre=[]
def rec(n):
    pre.append(n); [rec(k) for k in kids[n]]
rec(src); print("preorder consistent:", pre==order)
def path(n):
    p=[n]
    while p[-1]!=src: p.append(par[p[-1]])
