parameters.command:
python3 -I - <<'EOF'
import json
f='/Users/sbr/.claude/projects/-Users-sbr-gds-agent-benchmarks/6781022e-98c7-47b8-aa66-1387e9a51265/tool-results/toolu_01EEmff8CVRJPozeoct9xadD.json'
d=json.load(open(f)); t=d[0]['text'] if isinstance(d,list) else d
E=json.loads(t)[0]['e']
nodes=set(a for a,b in E)|set(b for a,b in E)
N=302; out={}
for a,b in E: out[a]=out.get(a,0)+1
avg=len(E)/N; dmp=0.8
s={n:(0.2 if n=='Paddington' else 0) for n in nodes}
for _ in range(20):
  ns={n:(0.2 if n=='Paddington' else 0) for n in nodes}
  for a,b in E: ns[b]+=dmp*s[a]/(out[a]+avg)
  s=ns
print(s['Paddington'],s['Bayswater'],len(nodes))
EOF

