mkdir -p /tmp/bcv && cd /tmp/bcv && cat > q.cypher <<'EOF'
EOF
cat > /tmp/bcv/bc.py <<'EOF'
import json,sys,collections
edges=[tuple(e.split('>')) for e in json.load(open(sys.argv[1]))]
adj=collections.defaultdict(list); nodes=set()
for a,b in edges: adj[a].append(b); nodes|={a,b}
bc=dict.fromkeys(nodes,0.0)
for s in nodes:
    S=[];P=collections.defaultdict(list);sig=collections.Counter({s:1});d={s:0};Q=collections.deque([s])
    while Q:
        v=Q.popleft();S.append(v)
        for w in adj[v]:
            if w not in d: d[w]=d[v]+1;Q.append(w)
            if d[w]==d[v]+1: sig[w]+=sig[v];P[w].append(v)
    delta=collections.Counter()
    while S:
        w=S.pop()
        for v in P[w]: delta[v]+=sig[v]/sig[w]*(1+delta[w])
        if w!=s: bc[w]+=delta[w]
print("multi-edge Brandes: Waterloo",bc['279'],"Westminster",bc['285'])
try:
    import networkx as nx
    G=nx.DiGraph(); G.add_edges_from(edges)
    b=nx.betweenness_centrality(G,normalized=False)
    print("networkx simple DiGraph: Waterloo",b['279'],"Westminster",b['285'])
except ImportError: print("no networkx")
EOF
echo ok

