parameters.query:
MATCH (a:UndergroundStation)-[:LINK]-(x)-[:LINK]-(b:UndergroundStation) WHERE elementId(a) < elementId(b) WITH a, b, count(DISTINCT x) AS inter
CALL (a) { MATCH (a)-[:LINK]-(n) RETURN count(DISTINCT n) AS da }
CALL (b) { MATCH (b)-[:LINK]-(n) RETURN count(DISTINCT n) AS db }
RETURN a.name, b.name, inter / sqrt(da*db) AS cos ORDER BY cos DESC LIMIT 12

