parameters.command:
cd /tmp && python3 - <<'EOF'
exec(open('dfs_paths.py').read().split('depth={')[0])
depth={"Aldgate":0}; parent={"Aldgate":None}
for u in order:
    assert u in depth, u
    if depth[u]<4:
        for v in adj.get(u,()):
            if v not in depth: depth[v]=depth[u]+1; parent[v]=u
assert set(depth)==set(order)
def path(v):
    r=[]
    while v: r.append(v); v=parent[v]
    return r[::-1]
for v in order:
    if v not in parent.values(): print(path(v))
EOF

